// Modelo simplificado de cómo se emparejan los hijos de una lista. NO es el código de React.
function emparejar(viejos, nuevos, claveDe) {
  const porClave = new Map(viejos.map((p, i) => [claveDe(p, i), p]));
  let reusados = 0, textosQueCambian = 0, filasNuevas = 0;
  nuevos.forEach((p, i) => {
    const v = porClave.get(claveDe(p, i));
    if (!v) filasNuevas++;
    else { reusados++; if (v.nombre !== p.nombre) textosQueCambian++; }
  });
  return { reusados, textosQueCambian, filasNuevas, filasQuitadas: viejos.length - reusados };
}

const viejos = Array.from({ length: 1000 }, (_, i) => ({ id: "p" + i, nombre: "pedido " + i }));
const nuevos = [{ id: "z0", nombre: "pedido nuevo" }, ...viejos]; // entra uno arriba

console.log("key = posición:", JSON.stringify(emparejar(viejos, nuevos, (p, i) => i)));
console.log("key = id      :", JSON.stringify(emparejar(viejos, nuevos, (p) => p.id)));
